/* Payly responsive prototype, persisted locally per browser. All people and payments are demo data.
   When Supabase is configured, authenticated cloud mode is started by cloud.js. Real payments and receipt OCR are still not connected. */
(() => {
  'use strict';
  if (window.PAYLY_CONFIG?.supabaseUrl && window.PAYLY_CONFIG?.supabasePublishableKey) { window.PaylyCloud.start(); return; }
  const $app = document.getElementById('app');
  const IC = {
    home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
    chats:'<path d="M21 11.5a8.4 8.4 0 0 1-9 8.3 8.7 8.7 0 0 1-3.5-.8L3 21l1.8-5A8.5 8.5 0 1 1 21 11.5Z"/>',
    activity:'<path d="M4 18v-5m6 5V8m6 10v-9m5 9V4"/><path d="M2 21h20"/>',
    user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',
    users:'<path d="M16 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="8.5" cy="7" r="4"/><path d="M20 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>',
    plus:'<path d="M12 5v14M5 12h14"/>',
    chevron:'<path d="m9 18 6-6-6-6"/>',
    left:'<path d="m15 18-6-6 6-6"/>',
    down:'<path d="m6 9 6 6 6-6"/>',
    check:'<path d="m5 12 4 4L19 6"/>',
    x:'<path d="M18 6 6 18M6 6l12 12"/>',
    bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',
    search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',
    more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',
    copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/>',
    send:'<path d="m22 2-7 20-4-9-9-4Z"/><path d="M22 2 11 13"/>',
    receipt:'<path d="M5 3h14v18l-3-2-4 2-4-2-3 2Z"/><path d="M9 8h6M9 12h6M9 16h4"/>',
    calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 10h18"/>',
    wallet:'<rect x="2" y="5" width="20" height="16" rx="3"/><path d="M2 9h20m-5 5h2"/>',
    card:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20"/>',
    bank:'<path d="m2 9 10-6 10 6M4 10h16M5 10v9m5-9v9m4-9v9m5-9v9M2 21h20"/>',
    lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
    share:'<path d="M12 16V3m-5 5 5-5 5 5"/><path d="M5 13v7h14v-7"/>',
    edit:'<path d="m4 20 4.5-1 11-11-3.5-3.5-11 11L4 20Z"/><path d="m14 7 3.5 3.5"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
    camera:'<path d="M3 7h4l2-3h6l2 3h4v13H3Z"/><circle cx="12" cy="13" r="4"/>',
    globe:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/>',
    info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5m0-8h.01"/>',
    settings:'<path d="M12 15.5a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7Z"/><path d="m19.4 15 1 1.7-2 2-1.7-1-1.3.6-.4 2H9l-.4-2-1.3-.6-1.7 1-2-2 1-1.7L4 13.5l-2-.5v-3l2-.5.6-1.5-1-1.7 2-2 1.7 1L8.6 5 9 3h6l.4 2 1.3.6 1.7-1 2 2-1 1.7.6 1.5 2 .5v3l-2 .5Z"/>',
    refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6.1 9a7 7 0 0 1 12-2l1.9 5M4 12l1.9 5a7 7 0 0 0 12-2"/>',
    upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 17v4h16v-4"/>',
    sparkle:'<path d="m12 3 1.8 6.2L20 11l-6.2 1.8L12 19l-1.8-6.2L4 11l6.2-1.8ZM19 18l.8 2.2L22 21l-2.2.8L19 24l-.8-2.2L16 21l2.2-.8Z"/>',
    trash:'<path d="M3 6h18M8 6V4h8v2m3 0-1 15H6L5 6M10 10v7m4-7v7"/>',
    mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 7 10 7L22 7"/>',
    logout:'<path d="M10 17l5-5-5-5m5 5H3m9-9h7a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2h-7"/>'
  };
  const icon = (name,size=20) => `<svg class="ic" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${IC[name]||IC.info}</svg>`;
  const e = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const euro = n => new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR'}).format(Number(n)||0).replace(/\u00a0/g,'');
  const people = [{id:'you',name:'You',file:'alex'},{id:'max',name:'Max',file:'max'},{id:'sophie',name:'Sophie',file:'sophie'},{id:'leon',name:'Leon',file:'leon'},{id:'anna',name:'Anna',file:'anna'}];
  const screens = [
    {id:'home',title:'Home',desc:'Balances and what needs attention',ico:'home'},
    {id:'chats',title:'Chats',desc:'One-to-one and group conversations',ico:'chats'},
    {id:'group',title:'Group chat',desc:'Expenses, approvals and messages',ico:'users'},
    {id:'add',title:'Add expense',desc:'Flexible expense splitting',ico:'plus'},
    {id:'receipt',title:'Receipt scanning',desc:'Sample receipt experience',ico:'receipt'},
    {id:'request',title:'Payment request',desc:'Request, remind and settle',ico:'wallet'},
    {id:'payments',title:'Integrated payments',desc:'Interactive payment demonstration',ico:'card'},
    {id:'activity',title:'Activity',desc:'Money activity at a glance',ico:'activity'},
    {id:'recurring',title:'Recurring expenses',desc:'Subscriptions and shared bills',ico:'calendar'},
    {id:'invite',title:'Invite others',desc:'Join via a shareable link',ico:'share'}
  ];
  const initialDraft = () => ({title:'Dinner at L’Osteria',amount:'86.40',split:'Equally',people:['you','max','sophie','leon'],custom:{you:'21.60',max:'21.60',sophie:'21.60',leon:'21.60'},note:'',receipt:false});
  const state = {screen: new URLSearchParams(location.search).has('invite') ? 'guest' : 'home',history:[],gallery:false,toast:'',modal:null,query:'',draft:initialDraft(),currentChat:'max',chatInput:'',threadMessages:[],expenses:[],paid:false,owePaid:false,paymentAmount:'24.50',paymentDirection:'owed',reminded:false,approval:false,oweDispute:'',requestView:'owed',disputeDraft:'',expenseViewer:'',expenseQuestion:'',selectedMethod:'',inviteTab:'link',recurring:[{name:'Rent',amount:'1800.00',interval:'1st of each month',logo:'🏠'},{name:'Netflix',amount:'17.99',interval:'Monthly',logo:'🎬'},{name:'Spotify Family',amount:'17.99',interval:'Monthly',logo:'🟢'},{name:'Internet',amount:'34.90',interval:'Monthly',logo:'📶'},{name:'Gym',amount:'29.99',interval:'Monthly',logo:'🏋️'}],recDraft:{name:'',amount:'',interval:'Monthly'},receiptImage:'',receiptFilename:'',previewGuest:false};
  // Demo persistence is local to this browser. Never use it as a trusted financial ledger.
  const STORAGE_KEY = 'payly-demo-v2';
  const persistKeys = ['expenses','recurring','threadMessages','paid','owePaid','reminded','approval','oweDispute'];
  try {
    const previous = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
    for (const key of persistKeys) if (Object.prototype.hasOwnProperty.call(previous,key) &&
      (key !== 'expenses' && key !== 'recurring' && key !== 'threadMessages' || Array.isArray(previous[key]))) state[key]=previous[key];
  } catch (_) { /* Private browsing or unavailable storage: the demo still works. */ }
  function persist(){
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(Object.fromEntries(persistKeys.map(key=>[key,state[key]])))); }
    catch (_) { /* Best-effort local demo storage. */ }
  }
  const share = (expense,id) => expense.shares?.[id] ?? Math.round(expense.amount * 100 / (expense.people?.length || 1)) / 100;
  const approvalBadge = status => `<span class="approval-badge ${e(status)}">${status==='approved'?'✓ Approved':status==='disputed'?'! Disputed':'◷ Awaiting approval'}</span>`;
  const expenseStatus = x => x.people.filter(p=>p!=='you').map(id=>({id,status:x.approvals?.[id]||'pending',amount:share(x,id)}));
  const expenseDetail = x => {
    const selected=state.expenseViewer&&x.people.includes(state.expenseViewer)?state.expenseViewer:'';
    const statuses=expenseStatus(x);
    return `<div class="expense-review"><div class="review-title">${e(x.title)}</div><div class="review-total">${euro(x.amount)}</div><p class="review-help">Each person needs to approve their own share. This prototype can preview other people's responses locally; it does not impersonate real accounts.</p>
      ${x.people.map(id=>`<div class="review-line">${ava(id)}<div class="row-body"><strong>${e(people.find(p=>p.id===id)?.name||id)}</strong><div>${approvalBadge(id==='you'?'approved':x.approvals?.[id]||'pending')}</div>${x.disputes?.[id]?`<div class="review-comment">“${e(x.disputes[id])}”</div>`:''}</div><strong>${euro(share(x,id))}</strong></div>`).join('')}
      ${statuses.length?`<div class="preview-block"><strong>Try a recipient’s view</strong><span>Preview only · no external notification</span><div class="preview-choices">${statuses.map(y=>`<button class="preview-choice ${selected===y.id?'active':''}" data-action="expenseViewer" data-person="${e(y.id)}">${e(people.find(p=>p.id===y.id)?.name||y.id)}</button>`).join('')}</div></div>`:''}
      ${selected?`<div class="recipient-panel"><div class="row-sub">Previewing ${e(people.find(p=>p.id===selected)?.name||selected)}’s account</div><strong>Your share: ${euro(share(x,selected))}</strong>${approvalBadge(x.approvals?.[selected]||'pending')}${x.approvals?.[selected]!=='approved'?`<div class="recipient-actions">${greenButton('Approve my share','expenseApprove')}${greenButton('Question amount','expenseQuestion','outline')}</div>`:''}</div>`:''}</div>`;
  };
  const ava = (id,cl='') => {const p=people.find(p=>p.id===id)||{name:id,file:'alex'};return `<img class="avatar ${cl}" alt="${e(p.name)}" src="./assets/${p.file}.png" onerror="this.style.display='none'">`;};
  const ghostBtn = (name,action,extra='') => `<button class="icon-button ${extra}" type="button" data-action="${action}" aria-label="${e(name)}">${icon(name)}</button>`;
  const head = (title,opts={}) => `<div class="app-head">${opts.back!==false?ghostBtn('left','back','back'):''}<div class="head-content"><div class="head-title" ${opts.titleStyle?'style="'+opts.titleStyle+'"':''}>${title}</div>${opts.subtitle?`<div class="head-subtitle">${opts.subtitle}</div>`:''}</div>${opts.right||''}</div>`;
  const greenButton = (label,action,cls='green',attrs='') => `<button class="btn ${cls}" type="button" data-action="${action}" ${attrs}>${label}</button>`;
  const note = `<div class="callout">${icon('info',15)} This is a frontend demo. No money is moved and no external accounts are connected.</div>`;
  const nav = active => `<div class="bottom-nav"><button class="nav-item ${active==='home'?'active':''}" data-action="go" data-screen="home">${icon('home')}<span>Home</span></button><button class="nav-item ${active==='chats'?'active':''}" data-action="go" data-screen="chats">${icon('chats')}<span>Chats</span></button><button class="nav-plus" data-action="go" data-screen="add" aria-label="Add expense">${icon('plus',25)}</button><button class="nav-item ${active==='activity'?'active':''}" data-action="go" data-screen="activity">${icon('activity')}<span>Activity</span></button><button class="nav-item ${active==='profile'?'active':''}" data-action="go" data-screen="profile">${icon('user')}<span>Profile</span></button></div>`;
  const status = () => `<div class="statusbar"><span>9:41</span><div class="status-icons"><svg width="17" height="12" viewBox="0 0 17 12"><path d="M1 11V8h2v3zm4 0V6h2v5zm4 0V3h2v8zm4 0V1h2v10z" fill="currentColor"/></svg><svg width="16" height="12" viewBox="0 0 16 12"><path d="M1 4Q8-2 15 4M4 7q4-4 8 0M7 10l1-1 1 1" fill="none" stroke="currentColor" stroke-width="1.5"/></svg><svg width="20" height="12" viewBox="0 0 20 12"><rect x="1" y="2" width="16" height="9" rx="2" stroke="currentColor" fill="none"/><rect x="3" y="4" width="12" height="5" rx="1" fill="currentColor"/><path d="M18 5v3" stroke="currentColor" stroke-width="2"/></svg></div></div><div class="island"></div>`;
  function home(){
    const added=state.expenses.reduce((a,x)=>a+x.people.filter(id=>id!=='you').reduce((total,id)=>total+share(x,id),0),0);
    return `<div class="app-head home-header"><div class="head-left">${ava('you','lg')}<div class="greeting">Good morning,<strong>Alex! 👋</strong></div></div><button class="icon-button" data-action="go" data-screen="activity" aria-label="Notifications" style="position:relative">${icon('bell')}<i class="badge-dot"></i></button></div><div class="scroll-content"><div class="balance-card"><div class="balance-pair"><div><div class="balance-label">You are owed</div><div class="balance-number tabular">${euro(327.4+added)}</div></div><div><div class="balance-label">You owe</div><div class="balance-number tabular">€118.70</div></div></div><div class="balance-net">Net balance<strong class="tabular">${euro(208.7+added).replace('€','+€')}</strong></div><div class="spark"><span style="height:15px"></span><span style="height:27px"></span><span style="height:43px"></span></div></div><div class="section-heading"><h3>Needs attention</h3><button class="text-link" data-action="go" data-screen="activity">See all</button></div><div class="stack-card"><button class="attention-row" data-action="go" data-screen="request"><span class="status-circle red">${icon('chevron',13)}</span><div class="row-body"><div class="row-title">Max owes you €84.00</div><div class="row-sub">Dinner · 19 days ago</div></div>${icon('chevron',16)}</button><button class="attention-row" data-action="go" data-screen="recurring"><span class="status-circle yellow">${icon('clock',13)}</span><div class="row-body"><div class="row-title">Apartment</div><div class="row-sub">Electricity · €32.20 · due tomorrow</div></div>${icon('chevron',16)}</button><button class="attention-row" data-action="go" data-screen="activity"><span class="status-circle green">${icon('check',13)}</span><div class="row-body"><div class="row-title">Sophie paid you €18.40</div><div class="row-sub">2 minutes ago</div></div>${icon('chevron',16)}</button>${state.expenses.slice(-2).reverse().map(x=>`<button class="attention-row" data-action="go" data-screen="group"><span class="status-circle green">${icon('check',13)}</span><div class="row-body"><div class="row-title">${e(x.title)} · ${euro(x.amount)}</div><div class="row-sub">${expenseStatus(x).filter(y=>y.status==='pending').length} approvals pending · Apartment</div></div>${icon('chevron',16)}</button>`).join('')}</div><div class="section-heading"><h3>Your spaces</h3><button class="text-link" data-action="go" data-screen="chats">See all</button></div><div class="stack-card"><button class="attention-row" data-action="go" data-screen="group"><span class="group-icon">🏠</span><div class="row-body"><div class="row-title">Apartment</div><div class="row-sub">4 members · 3 shared bills</div></div>${icon('chevron',16)}</button><button class="attention-row" data-action="go" data-screen="chats"><span class="group-icon blue">✈️</span><div class="row-body"><div class="row-title">Japan 2027</div><div class="row-sub">Planning the next trip</div></div>${icon('chevron',16)}</button></div></div>${nav('home')}`;
  }
  const chatData = [{id:'group',name:'Apartment',text:'Max: “I added the electricity bill”',time:'10:24',emoji:'🏠'},{id:'group',name:'Japan 2027',text:'You: Added a new expense',time:'09:41',emoji:'✈️',blue:1},{id:'direct',name:'Max',text:'You: Reminder sent',time:'Yesterday',who:'max'},{id:'direct',name:'Sophie',text:'Sophie paid you €18.40',time:'Yesterday',who:'sophie'},{id:'group',name:'Family',text:'Tom: “Birthday gift?”',time:'Sun',emoji:'👨‍👩‍👧‍👦',green:1},{id:'direct',name:'Lisa',text:'You: €24.50 for dinner',time:'Sat',who:'lisa'},{id:'group',name:'Weekend Trip',text:'Anna: “Looks good!”',time:'Fri',emoji:'🛜',blue:1}];
  function chats(){let rows=chatData.filter(c=>(c.name+' '+c.text).toLowerCase().includes(state.query.toLowerCase()));return `${head('Chats',{back:false,right:ghostBtn('edit','newchat')})}<div class="search-box">${icon('search',18)}<input data-field="query" aria-label="Search chats" value="${e(state.query)}" placeholder="Search chats...">${icon('plus',16)}</div><div class="scroll-content">${rows.length?rows.map(c=>`<button class="chat-row" data-action="chat" data-chat="${e(c.who||c.name)}" data-kind="${c.id}">${c.who?ava(c.who):`<span class="group-icon ${c.blue?'blue':c.green?'green':''}">${c.emoji}</span>`}<div class="row-body"><div class="row-title">${e(c.name)}</div><div class="row-sub">${e(c.text)}</div></div><div class="row-time">${e(c.time)}</div></button>`).join(''):`<div class="empty-state">No matching chats.</div>`}</div>${nav('chats')}`;}
  function group(){return `<div class="app-head" style="border-bottom:1px solid #e8eceb">${ghostBtn('left','back','back')}<span class="group-icon">🏠</span><div class="head-content"><div style="font-weight:800;font-size:15px">Apartment</div><div class="head-subtitle">4 members</div></div>${ghostBtn('more','groupmore')}</div><div class="chat-thread"><div class="thread-scroll" id="threadScroll"><div class="message-line">${ava('max','sm')}<div class="message-body"><div class="msg-author">Max</div><div class="chat-bubble">I added the electricity bill!</div><div class="msg-time">10:24</div></div></div><div class="message-line">${ava('max','sm')}<div class="message-body"><div class="expense-bubble"><div class="expense-row-head"><span class="expense-icon">🏠</span><div><strong style="font-size:14px">Electricity</strong><div class="expense-amount">€87.20</div><div class="subdued">Split equally · 4 people</div></div></div>${greenButton('Review your share','billdetail')}</div><div class="msg-time">10:24</div></div></div><div class="message-line">${ava('sophie','sm')}<div class="message-body"><div class="msg-author">Sophie</div><div class="chat-bubble">Looks good!</div><div class="msg-time">10:25</div></div></div><div class="message-line">${ava('leon','sm')}<div class="message-body"><div class="msg-author">Leon</div><div class="chat-bubble small-green">✓ Approved</div><div class="msg-time">10:26</div></div></div><div class="message-line mine">${ava('you','sm')}<div class="message-body"><div class="chat-bubble small-green">${state.approval?'✓ Approved':state.oweDispute?'! Disputed':'◷ Needs your approval'}</div><div class="msg-time">10:27</div></div></div>${state.expenses.map(x=>`<div class="message-line mine">${ava('you','sm')}<div class="message-body"><div class="expense-bubble"><strong>${e(x.title)}</strong><div class="expense-amount">${euro(x.amount)}</div><div class="subdued">${e(x.split)} · ${x.people.length} people</div><div class="approval-summary">${expenseStatus(x).map(y=>`<span>${e(people.find(p=>p.id===y.id)?.name||y.id)}: ${approvalBadge(y.status)}</span>`).join('')}</div><button class="btn green" data-action="expenseDetail" data-id="${e(x.id)}">View approvals</button></div><div class="msg-time">Just now</div></div></div>`).join('')}${state.threadMessages.map(m=>`<div class="message-line mine">${ava('you','sm')}<div class="message-body"><div class="chat-bubble">${e(m)}</div><div class="msg-time">Just now</div></div></div>`).join('')}</div><div class="chat-input"><button data-action="go" data-screen="add" aria-label="Add expense">${icon('plus',19)}</button><input data-field="chatInput" value="${e(state.chatInput)}" placeholder="Write a message..." aria-label="Write a message"><button class="send" data-action="send" aria-label="Send message">${icon('send',17)}</button></div></div>`;}
  function add(){const count=state.draft.people.length;const amount=Number(state.draft.amount)||0;return `${head('Add expense',{right:`<button class="icon-button" data-action="saveexpense" aria-label="Save expense" style="color:#0a8751">${icon('check',25)}</button>`})}<div class="scroll-content form-scroll"><div class="field"><label for="expenseTitle">Title</label><input id="expenseTitle" data-field="draft.title" value="${e(state.draft.title)}" placeholder="What was it for?"></div><div class="field"><label for="expenseAmount">Amount</label><div class="amount-input"><strong>€</strong><input id="expenseAmount" data-field="draft.amount" value="${e(state.draft.amount)}" inputmode="decimal" aria-label="Amount"><span class="currency">EUR ${icon('down',12)}</span></div></div><div class="field"><label>Split type</label><div class="segments">${['Equally','Custom','Percentage','Items'].map(x=>`<button class="${state.draft.split===x?'selected':''}" data-action="split" data-value="${x}">${x}</button>`).join('')}</div></div><div class="field" style="margin-bottom:4px"><label>Split between</label>${people.slice(0,4).map(p=>{let included=state.draft.people.includes(p.id);let val=state.draft.split==='Custom'?(state.draft.custom[p.id]??'0.00'):state.draft.split==='Percentage'?`${Math.round(100/Math.max(count,1))}%`:euro(amount/Math.max(count,1));return `<button class="participant-row" data-action="participant" data-person="${p.id}"><span class="check-round ${included?'checked':''}">${included?icon('check',13):''}</span>${ava(p.id)}<span class="participant-name">${p.name}</span><span class="participant-amount">${included?val:''}</span>${icon('down',13)}</button>`}).join('')}<button class="add-person" data-action="participant" data-person="anna">${icon('plus',16)} Add people ${state.draft.people.includes('anna')?'(Anna added)':''}</button>${state.draft.split==='Custom'?`<div class="callout">Custom split: edit each person’s amount using the small adjustment below. Total must equal the expense amount.</div>${state.draft.people.map(id=>`<div class="field" style="display:flex;gap:10px;align-items:center;margin:6px 0"><label style="flex:1;margin:0">${e(people.find(p=>p.id===id)?.name||id)}</label><input style="width:90px" inputmode="decimal" data-custom="${id}" value="${e(state.draft.custom[id]||'0.00')}"></div>`).join('')}`:''}${state.draft.split==='Percentage'?`<div class="callout">Percentage splits are illustrated evenly in this demo; use Custom for specific amounts.</div>`:''}${state.draft.split==='Items'?`<div class="callout">For item-by-item splitting, try the sample receipt screen.</div>`:''}</div><div class="field" style="margin-bottom:7px"><label>Add a receipt (optional)</label><div class="attach-row"><button class="small-file" type="button" data-action="go" data-screen="receipt" title="View sample receipt">${icon('receipt',22)}</button><label class="small-file add" title="Attach a receipt">${icon('plus',22)}<input type="file" accept="image/*" id="receiptUpload" style="display:none"></label>${state.receiptFilename?`<span class="subdued">${e(state.receiptFilename)}</span>`:''}</div></div><div class="field"><label for="expenseNote">Add a note (optional)</label><textarea id="expenseNote" data-field="draft.note" placeholder="e.g. Great dinner! 🍕">${e(state.draft.note)}</textarea></div>${greenButton('Add expense','saveexpense')}</div>`;}
  function receipt(){return `${head('Scan receipt')}<div class="wood-bg"><div class="receipt-paper"><h3>L’OSTERIA</h3><div class="paper-sub">PIZZA E PASTA</div>${[['Pizza Margherita','14,00'],['Pasta Carbonara','16,50'],['Insalata','12,50'],['Aperol Spritz','9,00'],['Coca Cola','4,50'],['Tiramisu','8,50']].map(([n,v])=>`<div class="receipt-line"><span>${n}</span><span>${v}</span></div>`).join('')}<div class="receipt-total"><strong>Total</strong><span>64,50</span></div><div style="text-align:center;margin-top:9px;font-size:11px">IVA incl.</div></div><div class="receipt-banner"><div style="display:flex;align-items:center;gap:11px"><span style="width:36px;height:36px;border-radius:50%;background:#ffffff22;display:grid;place-items:center">${icon('receipt',18)}</span><div style="flex:1;font-size:13px;font-weight:750">Sample receipt<br><span class="subdued">6 items · €64.50</span></div>${icon('check',17)}</div>${greenButton('Use sample expense','loadreceipt')}</div></div>`;}
  function request(){
    const owe = state.requestView === 'owe';
    const approved = state.approval;
    const status = state.oweDispute ? 'disputed' : approved ? 'approved' : 'pending';
    return `<div class="app-head" style="border-bottom:1px solid #eef1ee">${ghostBtn('left','back','back')}${ava('max')}<div class="head-content"><div style="font-weight:800;font-size:15px">Max</div></div>${ghostBtn('more','requestmore')}</div><div class="scroll-content" style="background:#f8fafd"><div class="request-toggle" role="group" aria-label="Choose request"><button class="${owe?'':'selected'}" data-action="requestView" data-view="owed">Max owes you</button><button class="${owe?'selected':''}" data-action="requestView" data-view="owe">You owe Max ${!approved&&!state.oweDispute?'•':''}</button></div>
      ${owe?`<div class="detail-card"><div class="request-icon">◷</div><div class="request-lead">Max requested from you</div><div class="big-money">€21.80</div><div class="row-sub">Electricity · Apartment</div><div class="status-wrap">${approvalBadge(status)}</div><p class="review-help">Max paid €87.20 for electricity, split equally between four people. Your share is €21.80.</p><div class="request-actions">${!approved?greenButton('Approve €21.80','approveOwe'):''}${!approved?greenButton(state.oweDispute?'Edit your question':'Question this amount','disputeOwe','outline'):''}${approved&&!state.owePaid?greenButton('View payment options','payOwe'):''}${state.owePaid?`<div class="due-pill">Demo payment completed</div>`:''}${greenButton('Back to group','go','plain','data-screen="group"')}</div></div>${state.oweDispute?`<div class="review-dispute"><strong>Your question</strong><p>${e(state.oweDispute)}</p><span>Demo only — Max has not actually been notified.</span></div>`:''}`:
      `<div class="detail-card"><div class="request-icon">◷</div><div class="request-lead">Max owes you</div><div class="big-money">${state.paid?'€0.00':'€24.50'}</div><div class="row-sub">Dinner · Aug 12</div><div class="due-pill">${icon(state.paid?'check':'clock',15)} ${state.paid?'Demo payment completed':'Awaiting Max’s payment'}</div><p class="review-help">Only Max can approve the money he owes. You cannot approve his share for him.</p><div class="request-actions">${state.paid?greenButton('See activity','goactivity'):greenButton('Preview payment','payOwed')}${!state.paid?greenButton(state.reminded?'Reminder recorded ✓':'Send reminder','remind','outline'):''}${greenButton('Edit','editrequest','plain')}</div></div><div class="small-msg">${ava('max','sm')}<div><div class="small-msg-bubble">Thanks! I’ll send it soon.</div><div class="row-sub">14:22</div></div></div>${state.reminded?`<div class="small-msg" style="justify-content:flex-end"><div><div class="small-msg-bubble" style="background:#e3f5eb">Reminder recorded (demo)</div><div class="row-sub">Just now</div></div>${ava('you','sm')}</div>`:''}`}${note}</div>`;
  }
  function payments(){return `${head('Pay '+euro(state.paymentAmount),{titleStyle:'font-size:17px;text-align:center'})}<div class="scroll-content"><div style="font-weight:800;font-size:13px;margin:16px 19px 10px">Choose payment method</div><div class="methods"><button class="method-row" data-action="method" data-method="Apple Pay"><span class="method-mark" style="color:#080d0b">●</span><span class="method-text">Apple Pay</span>${icon('chevron',15)}</button><button class="method-row" data-action="method" data-method="Google Pay"><span class="method-mark google">G Pay</span><span class="method-text">Google Pay</span>${icon('chevron',15)}</button><button class="method-row" data-action="method" data-method="Card"><span class="method-mark">${icon('card',25)}</span><span class="method-text">Card<small>Visa, Mastercard, ...</small></span>${icon('chevron',15)}</button><button class="method-row" data-action="method" data-method="Bank transfer (SEPA)"><span class="method-mark">${icon('bank',25)}</span><span class="method-text">Bank transfer (SEPA)<small>Usually free</small></span>${icon('chevron',15)}</button><button class="method-row" data-action="method" data-method="PayPal"><span class="method-mark paypal">P</span><span class="method-text">PayPal</span>${icon('chevron',15)}</button></div><div class="fineprint">${icon('lock',15)} Prototype only. No card data is collected or processed.</div>${note}</div>`;}
  const activities = [{p:'sophie',t:'Sophie paid you',sub:'Dinner',time:'10:24',sum:'€18.40',positive:1},{p:'you',t:'You added an expense',sub:'Dinner at L’Osteria',time:'09:41',sum:'−€86.40'},{p:'max',t:'Max approved your request',sub:'Dinner',time:'18:20',sum:'€24.50'},{p:'leon',t:'Leon paid you',sub:'Electricity',time:'14:11',sum:'€32.20',positive:1}];
  function activity(){return `${head('Activity',{back:false})}<div class="scroll-content"><div class="activity-heading">Today</div><div class="stack-card">${activities.slice(0,2).map(item=>activityRow(item)).join('')}${state.expenses.map(x=>activityRow({p:'you',t:'You added an expense',sub:x.title,time:'Just now',sum:'−'+euro(x.amount)})).join('')}${state.approval?activityRow({p:'you',t:'You approved your share',sub:'Electricity',time:'Just now',sum:'€21.80'}):''}${state.oweDispute?activityRow({p:'you',t:'You questioned your share',sub:'Electricity',time:'Just now',sum:'€21.80'}):''}${state.paid?activityRow({p:'max',t:'Demo settlement completed',sub:'Dinner',time:'Just now',sum:'€24.50',positive:1}):''}</div><div class="activity-heading">Yesterday</div><div class="stack-card">${activities.slice(2).map(item=>activityRow(item)).join('')}</div></div>${nav('activity')}`;}
  function activityRow(a){return `<button class="activity-row" data-action="go" data-screen="${a.t.includes('expense')?'group':'request'}">${ava(a.p)}<div class="row-body"><div class="row-title">${e(a.t)}</div><div class="row-sub">${e(a.sub)}<br>${e(a.time)}</div></div><div class="amount ${a.positive?'positive':'negative'}">${e(a.sum)}</div></button>`;}
  function recurring(){return `${head('Recurring expenses',{right:ghostBtn('plus','newrecurring')})}<div class="scroll-content"><div class="stack-card" style="margin-top:13px">${state.recurring.map((r,i)=>`<button class="bill-row" data-action="bill" data-index="${i}"><span class="bill-icon">${r.logo}</span><div class="row-body"><div class="row-title">${e(r.name)}</div><div class="row-sub">${e(r.interval)}</div></div><div class="bill-value">${euro(r.amount)}</div>${icon('chevron',15)}</button>`).join('')}</div>${note}</div>`;}
  const guestLink = () => location.href.split('?')[0].split('#')[0]+'?invite=apartment';
  function invite(){return `${head('Invite people')}<div class="scroll-content"><div class="invite-tabs"><button data-action="inviteTab" data-tab="link" class="${state.inviteTab==='link'?'active':''}">Invite via link</button><button data-action="inviteTab" data-tab="qr" class="${state.inviteTab==='qr'?'active':''}">Invite via QR</button></div>${state.inviteTab==='link'?`<div class="invite-link"><span>${e(guestLink())}</span><button data-action="copy" aria-label="Copy link" class="icon-button">${icon('copy',19)}</button></div><div class="invite-help">Anyone with this link can preview this group in the demo.</div><div class="share-card">${greenButton('Share link','share')}<div class="share-divider">Or invite via</div><div class="share-apps"><button data-action="share" class="share-app"><span>🟢</span>WhatsApp</button><button data-action="share" class="share-app"><span>💬</span>Messages</button><button data-action="share" class="share-app"><span>✉️</span>Email</button><button data-action="share" class="share-app"><span>${icon('more')}</span>More</button></div></div>`:`<div class="qr-art" aria-label="Decorative QR preview, not scannable"></div><div class="invite-help">QR preview only — use the link tab for a working local demo URL.</div>`}${note}</div>`;}
  function profile(){return `${head('Profile',{back:false})}<div class="scroll-content"><div style="display:flex;align-items:center;gap:14px;margin:20px 18px 27px">${ava('you','lg')}<div><strong style="font-size:18px">Alex Morgan</strong><div class="row-sub">Your demo profile</div></div></div><div class="stack-card"><button class="profile-item" data-action="go" data-screen="recurring">${icon('calendar')}<span>Recurring expenses</span>${icon('chevron')}</button><button class="profile-item" data-action="go" data-screen="invite">${icon('share')}<span>Invite people</span>${icon('chevron')}</button><button class="profile-item" data-action="reset">${icon('refresh')}<span>Reset demo data</span>${icon('chevron')}</button></div>${note}</div>${nav('profile')}`;}
  function guest(){return `${head('Group invitation',{back:false})}<div class="scroll-content"><div style="text-align:center;margin:42px 20px 0"><div class="group-icon" style="width:75px;height:75px;margin:auto;font-size:35px;border-radius:22px">🏠</div><h2 style="font-size:25px;margin:20px 0 7px">Apartment</h2><p style="color:#788b80;font-size:13px">Alex invited you to a shared money space.</p><div class="stack-card" style="margin:35px 0 16px;padding:20px;text-align:left"><strong>Apartment</strong><div class="row-sub">4 members · Shared bills and expenses</div><div class="small-divider"></div><div style="display:flex;gap:7px">${['max','sophie','leon','you'].map(p=>ava(p)).join('')}</div></div>${greenButton('Explore demo group','joinGuest')}${greenButton('Back to Payly','go','outline','data-screen="home"')}</div>${note}</div>`;}
  function success(){return `${head('Payment demo')}<div class="scroll-content"><div class="status-success"><div class="success-mark">${icon('check',43)}</div><h2>All settled!</h2><p>A ${euro(state.paymentAmount)} payment was simulated successfully.<br>No real money was moved.</p>${greenButton('Back to home','go','green','data-screen="home"')}${greenButton('See activity','go','outline','data-screen="activity"')}</div></div>`;}
  function direct(){return `<div class="app-head" style="border-bottom:1px solid #eef2ee">${ghostBtn('left','back','back')}${ava(state.currentChat)}<div class="head-content"><strong>${e(state.currentChat.charAt(0).toUpperCase()+state.currentChat.slice(1))}</strong><div class="head-subtitle">Personal money chat</div></div>${ghostBtn('more','requestmore')}</div><div class="chat-thread"><div class="thread-scroll"><div class="message-line">${ava(state.currentChat,'sm')}<div class="message-body"><div class="chat-bubble">Thanks! I'll send it soon.</div><div class="msg-time">Yesterday</div></div></div><div class="message-line mine">${ava('you','sm')}<div class="message-body"><div class="expense-bubble"><div class="row-sub">Dinner · Aug 12</div><div class="expense-amount">€24.50</div><div class="row-sub">Max owes you</div>${greenButton('Open request','go','green','data-screen="request"')}</div></div></div>${state.threadMessages.map(m=>`<div class="message-line mine">${ava('you','sm')}<div class="message-body"><div class="chat-bubble">${e(m)}</div><div class="msg-time">Just now</div></div></div>`).join('')}</div><div class="chat-input"><button data-action="go" data-screen="add" aria-label="Add expense">${icon('plus')}</button><input data-field="chatInput" placeholder="Write a message..." value="${e(state.chatInput)}"><button class="send" data-action="send" aria-label="Send message">${icon('send',17)}</button></div></div>`;}
  const draw = {home,chats,group,add,receipt,request,payments,activity,recurring,invite,profile,guest,success,direct};
  function renderScreen(name){return draw[name]?draw[name]():home();}
  function renderPhone(name,forGallery=false){return `<div class="phone"><div class="phone-inner">${status()}<div class="screen-main">${renderScreen(name)}</div><div class="home-indicator"></div>${!forGallery&&state.toast?`<div class="toast" role="status">${e(state.toast)}</div>`:''}${!forGallery&&state.modal?modal():''}</div></div>`;}
  function modal(){let m=state.modal;
    if(m.type==='expense')return `<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true">${expenseDetail(m.expense)}<div class="modal-actions">${greenButton('Close','closemodal','plain')}</div></div></div>`;
    if(m.type==='expenseDispute')return `<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true"><h2>Question ${e(m.expense.title)}</h2><p>You’re previewing ${e(people.find(p=>p.id===m.person)?.name||m.person)}’s response to their ${euro(share(m.expense,m.person))} share.</p><div class="field"><label for="expenseQuestion">Question</label><textarea id="expenseQuestion" data-field="expenseQuestion" rows="3" placeholder="What needs to change?">${e(state.expenseQuestion)}</textarea></div><div class="modal-actions">${greenButton('Cancel','closemodal','plain')}${greenButton('Send question','submitExpenseDispute')}</div></div></div>`;
    if(m.type==='dispute')return `<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true"><h2>Question this amount</h2><p>Why does your €21.80 electricity share need reviewing?</p><div class="field"><label for="questionText">Your message</label><textarea id="questionText" data-field="disputeDraft" rows="3" placeholder="e.g. I was away this month…">${e(state.disputeDraft||state.oweDispute)}</textarea></div><div class="modal-actions">${greenButton('Cancel','closemodal','plain')}${greenButton('Send question','submitDispute')}</div></div></div>`;
    if(m.type==='pay')return `<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true"><span class="demo-tag">DEMO CHECKOUT</span><h2>${e(m.method)}</h2><p>Simulate settling ${euro(state.paymentAmount)} with ${e(m.method)}. There is no payment provider or backend connected.</p><div class="modal-actions">${greenButton('Cancel','closemodal','plain')}${greenButton('Simulate payment','simulate')}</div></div></div>`;if(m.type==='recurring')return `<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true"><h2>New recurring bill</h2><p>Create a sample recurring expense on this device.</p><div class="field"><label>Name</label><input data-field="recDraft.name" placeholder="e.g. Electricity" value="${e(state.recDraft.name)}"></div><div class="field"><label>Amount (€)</label><input inputmode="decimal" data-field="recDraft.amount" placeholder="0.00" value="${e(state.recDraft.amount)}"></div><div class="field"><label>Repeats</label><select data-field="recDraft.interval"><option ${state.recDraft.interval==='Monthly'?'selected':''}>Monthly</option><option ${state.recDraft.interval==='Weekly'?'selected':''}>Weekly</option><option ${state.recDraft.interval==='Yearly'?'selected':''}>Yearly</option></select></div><div class="modal-actions">${greenButton('Cancel','closemodal','plain')}${greenButton('Save bill','saverecurring')}</div></div></div>`;if(m.type==='bill')return `<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true"><h2>${e(m.name)}</h2><p>${e(m.interval)} · ${euro(m.amount)}</p><p>Recurring items here are example data. No charges will be scheduled.</p><div class="modal-actions">${greenButton('Close','closemodal','plain')}${greenButton('View group','go','green','data-screen="group"')}</div></div></div>`;return `<div class="modal-overlay"><div class="modal" role="dialog" aria-modal="true"><h2>${e(m.title||'Demo feature')}</h2><p>${e(m.message||'This feature will be connected in a later version.')}</p>${greenButton('Got it','closemodal')}</div></div>`;}
  const galleryText = `This is a visual-only prototype with local interactions, not a live fintech service. No real transactions, payment processing or receipt recognition.`;
  function render(){
    if(state.gallery){$app.innerHTML=`<div class="app-shell"><header class="topbar"><div class="brand-wrap"><div class="brand">Payly</div><div class="tagline">Money between people, simplified.</div></div><div class="top-actions"><span class="demo-tag">INTERACTIVE UI DEMO</span><button class="top-action primary" data-action="gallery">${icon('left',17)} Back to app</button></div></header><main class="gallery-view"><div class="gallery-header"><div><h1>Every screen, one simple experience.</h1><p>Select any phone to explore its interactive version.</p></div><button class="top-action" data-action="reset">${icon('refresh',16)} Reset demo</button></div><div class="gallery-grid">${screens.map(s=>`<button class="gallery-card" data-action="openFromGallery" data-screen="${s.id}"><div class="gallery-viewport">${renderPhone(s.id,true)}</div><div><h3>${e(s.title)}</h3><p>${e(s.desc)}</p></div></button>`).join('')}</div><div class="below-note" style="margin:32px auto;max-width:600px">${galleryText}</div></main></div>`;
      requestAnimationFrame(()=>document.querySelectorAll('.gallery-viewport').forEach(v=>{const w=v.getBoundingClientRect().width;v.style.setProperty('--thumb-scale',Math.min(1,w/394));}));
    } else {$app.innerHTML=`<div class="app-shell"><header class="topbar"><div class="brand-wrap"><div class="brand">Payly</div><div class="tagline">Money between people, simplified.</div></div><div class="top-actions"><span class="demo-tag">UI PROTOTYPE</span><button class="top-action" data-action="reset">${icon('refresh',16)} Reset</button><button class="top-action primary" data-action="gallery">${icon('users',16)} All 10 screens</button></div></header><main class="workspace"><section class="intro"><div class="eyebrow">${icon('sparkle',15)} Made for money between people</div><h1>Share more.<br>Worry less.</h1><p>All the money between you and the people in your life — in one beautiful, simple place.</p><div class="feature-pills"><span>Money chats</span><span>Split expenses</span><span>Settle up</span><span>Shared spaces</span></div><button class="intro-button" data-action="gallery">Explore all 10 screens ${icon('chevron',17)}</button><p class="soft-note">${galleryText}</p></section><section class="device-column">${renderPhone(state.screen)}<div class="bottom-device-caption">Interactive demo · ${e(screens.find(x=>x.id===state.screen)?.title||'Payly')}</div></section><aside class="screen-list"><div class="panel-overline">Explore the experience</div><h2>Inside Payly</h2><p>Choose a screen to explore the complete mobile interface.</p><div class="screens-box">${screens.map(s=>`<button class="screen-selector ${state.screen===s.id?'active':''}" data-action="go" data-screen="${s.id}"><span class="selector-icon">${icon(s.ico,18)}</span><span class="selector-label"><strong>${e(s.title)}</strong><small>${e(s.desc)}</small></span>${icon('chevron',14)}</button>`).join('')}</div><div class="below-note"><b>Frontend only, by design.</b><br>All interactions use example data. Real accounts, payments, invitations and receipt scanning will be wired up later.</div></aside></main></div>`;}
    const scroll=document.getElementById('threadScroll');if(scroll&&state.threadMessages.length)scroll.scrollTop=scroll.scrollHeight;
  }
  function go(target){if(!draw[target])return;if(target!==state.screen){state.history.push(state.screen);state.screen=target;}state.toast='';state.modal=null;render();}
  function back(){if(state.modal){state.modal=null;render();return;}state.screen=state.history.pop()||(state.screen==='group'?'chats':'home');state.toast='';render();}
  function toast(s){state.toast=s;render();}
  const normalizeAmount = x => {let n=Number(String(x).replace(',','.').replace(/[^\d.]/g,''));return Number.isFinite(n)?Math.round(n*100)/100:0;};
  async function copyInvite(){const link=guestLink();try{await navigator.clipboard.writeText(link);toast('Demo invitation link copied!');}catch(_){state.modal={type:'info',title:'Copy demo link',message:link};render();}}
  $app.addEventListener('click',async ev=>{
    const b=ev.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;ev.preventDefault();
    if(a==='gallery'){if(window.matchMedia&&window.matchMedia('(max-width:650px)').matches){state.gallery=false;render();return;}state.gallery=!state.gallery;state.toast='';render();window.scrollTo(0,0);return;}
    if(a==='openFromGallery'){state.gallery=false;state.screen=b.dataset.screen;state.history=[];render();window.scrollTo(0,0);return;}
    if(a==='go'){go(b.dataset.screen);return;}
    if(a==='back'){back();return;}
    if(a==='chat'){state.currentChat=b.dataset.chat.toLowerCase();go(b.dataset.kind==='group'?'group':'direct');return;}
    if(a==='split'){state.draft.split=b.dataset.value;render();return;}
    if(a==='participant'){const p=b.dataset.person;if(state.draft.people.includes(p)){if(state.draft.people.length===1){toast('Select at least one person.');return;}state.draft.people=state.draft.people.filter(x=>x!==p);}else state.draft.people.push(p);if(state.draft.split==='Equally')for(const id of state.draft.people)state.draft.custom[id]=((normalizeAmount(state.draft.amount)||0)/state.draft.people.length).toFixed(2);render();return;}
    if(a==='saveexpense'){const d=state.draft;let n=normalizeAmount(d.amount);if(!d.title.trim()||n<=0){toast('Enter a title and an amount greater than €0.');return;}if(d.split==='Custom'){const total=d.people.reduce((s,p)=>s+normalizeAmount(d.custom[p]),0);if(Math.abs(total-n)>.011){toast(`Custom shares must total ${euro(n)} (now ${euro(total)}).`);return;}}const cents=Math.round(n*100);const shares={};
      if(d.split==='Custom'){for(const id of d.people)shares[id]=normalizeAmount(d.custom[id]);}
      else {const base=Math.floor(cents/d.people.length),remainder=cents%d.people.length;d.people.forEach((id,i)=>shares[id]=(base+(i<remainder?1:0))/100);}
      const approvals=Object.fromEntries(d.people.filter(id=>id!=='you').map(id=>[id,'pending']));
      state.expenses.push({id:typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random(),title:d.title.trim(),amount:n,people:[...d.people],split:d.split,note:d.note,shares,approvals});persist();state.draft=initialDraft();state.history=['chats'];state.screen='group';state.toast='Expense added to Apartment (demo).';render();return;}
    if(a==='loadreceipt'){state.draft.title='Dinner at L’Osteria';state.draft.amount='64.50';state.draft.receipt=true;state.draft.split='Items';state.draft.custom={you:'16.12',max:'16.13',sophie:'16.12',leon:'16.13'};state.screen='add';state.toast='Sample receipt loaded — no OCR was used.';render();return;}
    if(a==='send'){let msg=state.chatInput.trim();if(!msg){toast('Write a message first.');return;}state.threadMessages.push(msg);state.chatInput='';persist();render();return;}
    if(a==='billdetail'){state.requestView='owe';go('request');return;}
    if(a==='expenseDetail'){const x=state.expenses.find(x=>String(x.id)===b.dataset.id);if(x){state.expenseViewer='';state.modal={type:'expense',expense:x};render();}return;}
    if(a==='expenseViewer'){state.expenseViewer=b.dataset.person;render();return;}
    if(a==='expenseApprove'){const x=state.modal?.expense,id=state.expenseViewer;if(!x||!id||id==='you'||!x.people.includes(id))return;x.approvals[id]='approved';if(x.disputes)delete x.disputes[id];persist();toast('Share approved in recipient preview (demo).');return;}
    if(a==='expenseQuestion'){const x=state.modal?.expense,id=state.expenseViewer;if(!x||!id||id==='you'||!x.people.includes(id))return;state.expenseQuestion=x.disputes?.[id]||'';state.modal={type:'expenseDispute',expense:x,person:id};render();return;}
    if(a==='submitExpenseDispute'){const x=state.modal?.expense,id=state.modal?.person;if(!x||!id||!x.people.includes(id))return;const message=state.expenseQuestion.trim();if(!message){toast('Write a question before submitting.');return;}x.approvals[id]='disputed';x.disputes??={};x.disputes[id]=message;persist();state.modal={type:'expense',expense:x};toast('Question recorded in recipient preview (demo).');return;}
    if(a==='requestView'){state.requestView=b.dataset.view;render();return;}
    if(a==='approveOwe'){state.approval=true;state.oweDispute='';state.disputeDraft='';persist();toast('You approved your €21.80 share (demo).');return;}
    if(a==='disputeOwe'){state.disputeDraft=state.oweDispute;state.modal={type:'dispute'};render();return;}
    if(a==='submitDispute'){if(!(state.disputeDraft||'').trim()){toast('Please explain what needs reviewing.');return;}state.oweDispute=state.disputeDraft.trim();state.approval=false;state.modal=null;persist();toast('Your question was recorded locally (demo).');return;}
    if(a==='remind'){state.reminded=true;persist();toast('Friendly reminder sent in this demo.');return;}
    if(a==='editrequest'){state.draft.title='Dinner';state.draft.amount='24.50';go('add');return;}
    if(a==='goactivity'){go('activity');return;}
    if(a==='payOwe'){if(!state.approval){toast('Approve your share before the payment preview.');return;}state.paymentAmount='21.80';state.paymentDirection='owe';go('payments');return;}
    if(a==='payOwed'){state.paymentAmount='24.50';state.paymentDirection='owed';go('payments');return;}
    if(a==='method'){state.modal={type:'pay',method:b.dataset.method};render();return;}
    if(a==='closemodal'){state.modal=null;render();return;}
    if(a==='simulate'){if(state.paymentDirection==='owe')state.owePaid=true;else state.paid=true;persist();state.modal=null;state.screen='success';state.history=['payments'];render();return;}
    if(a==='newrecurring'){state.recDraft={name:'',amount:'',interval:'Monthly'};state.modal={type:'recurring'};render();return;}
    if(a==='saverecurring'){let n=normalizeAmount(state.recDraft.amount);if(!state.recDraft.name.trim()||!n){toast('Enter a bill name and valid amount.');return;}state.recurring.push({name:state.recDraft.name.trim(),amount:n,interval:state.recDraft.interval,logo:'🧾'});state.modal=null;persist();toast('Recurring bill added to demo.');return;}
    if(a==='bill'){const r=state.recurring[Number(b.dataset.index)];state.modal={type:'bill',...r};render();return;}
    if(a==='inviteTab'){state.inviteTab=b.dataset.tab;render();return;}
    if(a==='copy'){await copyInvite();return;}
    if(a==='share'){if(navigator.share){try{await navigator.share({title:'Join my Payly demo',text:'Join my Payly Apartment group preview',url:guestLink()});}catch(_){}}else await copyInvite();return;}
    if(a==='joinGuest'){history.replaceState(null,'',location.pathname);go('group');return;}
    if(a==='groupmore'){state.modal={type:'info',title:'Apartment',message:'Shared space · 4 people. From a real version, manage your members, rules and notifications here.'};render();return;}
    if(a==='requestmore'){state.modal={type:'info',title:'Request options',message:'A full release will include history, disputes, edits, receipts and notification settings.'};render();return;}
    if(a==='newchat'){state.modal={type:'info',title:'New chat',message:'Contacts and invitations require the future backend. Explore the existing sample chats for now.'};render();return;}
    if(a==='reset'){try{localStorage.removeItem(STORAGE_KEY);}catch(_){}Object.assign(state,{screen:'home',history:[],gallery:false,toast:'Demo data reset.',modal:null,query:'',draft:initialDraft(),currentChat:'max',chatInput:'',threadMessages:[],expenses:[],paid:false,owePaid:false,paymentAmount:'24.50',paymentDirection:'owed',reminded:false,approval:false,oweDispute:'',requestView:'owed',disputeDraft:'',expenseViewer:'',expenseQuestion:'',selectedMethod:'',inviteTab:'link',recurring:[{name:'Rent',amount:'1800.00',interval:'1st of each month',logo:'🏠'},{name:'Netflix',amount:'17.99',interval:'Monthly',logo:'🎬'},{name:'Spotify Family',amount:'17.99',interval:'Monthly',logo:'🟢'},{name:'Internet',amount:'34.90',interval:'Monthly',logo:'📶'},{name:'Gym',amount:'29.99',interval:'Monthly',logo:'🏋️'}],recDraft:{name:'',amount:'',interval:'Monthly'},receiptImage:'',receiptFilename:'',disputeDraft:'',expenseViewer:'',expenseQuestion:''});render();return;}
  });
  $app.addEventListener('input',ev=>{const f=ev.target.dataset.field;if(f){const parts=f.split('.');if(parts.length===2)state[parts[0]][parts[1]]=ev.target.value;else state[f]=ev.target.value;}const custom=ev.target.dataset.custom;if(custom)state.draft.custom[custom]=ev.target.value;if(f==='query'){let start=ev.target.selectionStart;let end=ev.target.selectionEnd;render();let nxt=document.querySelector('[data-field="query"]');if(nxt){nxt.focus();nxt.setSelectionRange(start,end);}}});
  $app.addEventListener('change',ev=>{if(ev.target.id==='receiptUpload'&&ev.target.files?.[0]){state.receiptFilename=ev.target.files[0].name;toast('Receipt attached locally; automatic scanning is not connected.');}if(ev.target.dataset.field==='recDraft.interval')state.recDraft.interval=ev.target.value;});
  $app.addEventListener('keydown',ev=>{if(ev.key==='Enter'&&ev.target.dataset.field==='chatInput'){ev.preventDefault();let val=state.chatInput.trim();if(val){state.threadMessages.push(val);state.chatInput='';persist();render();}}});
  window.addEventListener('resize',()=>{if(state.gallery&&window.matchMedia&&window.matchMedia('(max-width:650px)').matches){state.gallery=false;render();return;}if(state.gallery)document.querySelectorAll('.gallery-viewport').forEach(v=>v.style.setProperty('--thumb-scale',Math.min(1,v.getBoundingClientRect().width/394)));});
  render();
})();
